"""Simulated target program with known CFG for deterministic fuzzing experiments."""

import numpy as np
from typing import List, Set, Tuple, Dict, Optional


class BasicBlock:
    """A basic block in the control flow graph."""

    def __init__(self, block_id: int, name: str = ""):
        self.block_id = block_id
        self.name = name or f"bb_{block_id}"


class Edge:
    """An edge in the control flow graph."""

    def __init__(self, edge_id: int, src: int, dst: int,
                 is_crash: bool = False, is_rare: bool = False):
        self.edge_id = edge_id
        self.src = src
        self.dst = dst
        self.is_crash = is_crash
        self.is_rare = is_rare


class SimulatedProgram:
    """A simulated target program with a known CFG.

    The program takes an input (bytes) and traces execution through the CFG
    based on input byte values. Returns which edges were hit.
    """

    def __init__(self, blocks: List[BasicBlock], edges: List[Edge],
                 entry_block: int = 0, target_blocks: Optional[List[int]] = None):
        self.blocks = {b.block_id: b for b in blocks}
        self.edges = edges
        self.edge_map: Dict[Tuple[int, int], Edge] = {}
        self.adj: Dict[int, List[Edge]] = {b.block_id: [] for b in blocks}
        self.entry_block = entry_block
        self.target_blocks = target_blocks or []

        for e in edges:
            self.edge_map[(e.src, e.dst)] = e
            self.adj[e.src].append(e)

    def execute(self, input_data: bytes) -> Tuple[Set[int], bool, float]:
        """Execute the program on the given input.

        Returns:
            (edges_hit, is_crash, exec_time)
            - edges_hit: set of edge IDs that were traversed
            - is_crash: whether a crash-triggering edge was hit
            - exec_time: simulated execution time (proportional to path length)
        """
        edges_hit = set()
        is_crash = False
        current_block = self.entry_block
        exec_time = 0.0
        input_pos = 0

        max_steps = 100  # prevent infinite loops

        for step in range(max_steps):
            outgoing = self.adj.get(current_block, [])
            if not outgoing:
                break

            # Determine which edge to take based on input byte
            if input_pos < len(input_data):
                byte_val = input_data[input_pos]
                input_pos += 1
            else:
                byte_val = 0

            # Select edge based on byte value modulo number of outgoing edges
            edge_idx = byte_val % len(outgoing)
            chosen_edge = outgoing[edge_idx]

            edges_hit.add(chosen_edge.edge_id)
            exec_time += 0.001  # 1ms per edge traversal

            if chosen_edge.is_crash:
                is_crash = True

            current_block = chosen_edge.dst

        return edges_hit, is_crash, exec_time

    def get_all_edge_ids(self) -> Set[int]:
        """Return all edge IDs in the program."""
        return {e.edge_id for e in self.edges}

    def get_crash_edges(self) -> Set[int]:
        """Return edge IDs that trigger crashes."""
        return {e.edge_id for e in self.edges if e.is_crash}

    def get_rare_edges(self) -> Set[int]:
        """Return edge IDs that are hard to reach."""
        return {e.edge_id for e in self.edges if e.is_rare}

    def get_shortest_distances(self, target_block_ids: List[int]) -> Dict[int, float]:
        """Compute shortest distance from each block to the nearest target block.

        Uses BFS/Dijkstra (all edges weight 1).
        Returns dict mapping block_id -> distance (inf if unreachable).
        """
        from collections import deque

        # Build reverse adjacency
        rev_adj: Dict[int, List[int]] = {bid: [] for bid in self.blocks}
        for e in self.edges:
            rev_adj[e.dst].append(e.src)

        distances: Dict[int, float] = {bid: float('inf') for bid in self.blocks}

        # BFS from each target block backwards
        queue = deque()
        for tb in target_block_ids:
            if tb in self.blocks:
                distances[tb] = 0.0
                queue.append(tb)

        while queue:
            node = queue.popleft()
            for pred in rev_adj.get(node, []):
                new_dist = distances[node] + 1.0
                if new_dist < distances[pred]:
                    distances[pred] = new_dist
                    queue.append(pred)

        return distances

"""Basic mutation operators for fuzzing.

All operators are deterministic given a numpy RandomState instance.
"""

import numpy as np
from typing import List


# Interesting values for different sizes (from AFL)
INTERESTING_8 = [-128, -1, 0, 1, 16, 32, 64, 100, 127]
INTERESTING_16 = [-32768, -129, 128, 255, 256, 512, 1000, 1024, 4096, 32767]
INTERESTING_32 = [-2147483648, -100663046, -32769, 32768, 65535, 65536,
                  100663045, 2147483647]


def bit_flip(data: bytes, pos: int, width: int = 1) -> bytes:
    """Flip 'width' consecutive bits starting at bit position 'pos'."""
    buf = bytearray(data)
    for i in range(width):
        bit_pos = pos + i
        byte_idx = bit_pos // 8
        bit_idx = bit_pos % 8
        if byte_idx < len(buf):
            buf[byte_idx] ^= (1 << (7 - bit_idx))
    return bytes(buf)


def byte_flip(data: bytes, pos: int, width: int = 1) -> bytes:
    """Flip 'width' consecutive bytes starting at position 'pos'."""
    buf = bytearray(data)
    for i in range(width):
        if pos + i < len(buf):
            buf[pos + i] ^= 0xFF
    return bytes(buf)


def arith_add(data: bytes, pos: int, value: int = 1) -> bytes:
    """Add a small value to byte at position 'pos'."""
    buf = bytearray(data)
    if pos < len(buf):
        buf[pos] = (buf[pos] + value) & 0xFF
    return bytes(buf)


def arith_sub(data: bytes, pos: int, value: int = 1) -> bytes:
    """Subtract a small value from byte at position 'pos'."""
    buf = bytearray(data)
    if pos < len(buf):
        buf[pos] = (buf[pos] - value) & 0xFF
    return bytes(buf)


def interesting_values(data: bytes, pos: int, rng: np.random.RandomState) -> bytes:
    """Replace byte at position with an interesting value."""
    buf = bytearray(data)
    if pos < len(buf):
        val = INTERESTING_8[rng.randint(0, len(INTERESTING_8))]
        buf[pos] = val & 0xFF
    return bytes(buf)


def random_byte(data: bytes, pos: int, rng: np.random.RandomState) -> bytes:
    """Replace byte at position with a random value."""
    buf = bytearray(data)
    if pos < len(buf):
        buf[pos] = rng.randint(0, 256)
    return bytes(buf)


def clone_bytes(data: bytes, src: int, dst: int, length: int) -> bytes:
    """Clone a chunk of bytes from src to dst position."""
    buf = bytearray(data)
    if src + length <= len(buf) and dst + length <= len(buf):
        chunk = buf[src:src + length]
        buf[dst:dst + length] = chunk
    return bytes(buf)


def delete_bytes(data: bytes, pos: int, length: int) -> bytes:
    """Delete 'length' bytes starting at position 'pos'."""
    buf = bytearray(data)
    if pos < len(buf):
        end = min(pos + length, len(buf))
        del buf[pos:end]
    if len(buf) == 0:
        buf = bytearray(b'\x00')
    return bytes(buf)


def insert_bytes(data: bytes, pos: int, new_bytes: bytes) -> bytes:
    """Insert new bytes at position 'pos'."""
    buf = bytearray(data)
    if pos <= len(buf):
        for i, b in enumerate(new_bytes):
            buf.insert(pos + i, b)
    return bytes(buf)


def havoc(data: bytes, rng: np.random.RandomState, num_mutations: int = 0) -> bytes:
    """Apply a random combination of mutations (AFL's havoc stage).

    If num_mutations is 0, randomly choose 1-7 mutations to stack.
    """
    if num_mutations == 0:
        num_mutations = rng.randint(1, 8)

    result = data
    for _ in range(num_mutations):
        if len(result) == 0:
            result = b'\x00'

        op = rng.randint(0, 8)
        pos = rng.randint(0, max(1, len(result)))

        if op == 0:
            # bit flip
            bit_pos = rng.randint(0, max(1, len(result) * 8))
            result = bit_flip(result, bit_pos)
        elif op == 1:
            # byte flip
            result = byte_flip(result, pos)
        elif op == 2:
            # arith add
            val = rng.randint(1, 36)
            result = arith_add(result, pos, val)
        elif op == 3:
            # arith sub
            val = rng.randint(1, 36)
            result = arith_sub(result, pos, val)
        elif op == 4:
            # interesting values
            result = interesting_values(result, pos, rng)
        elif op == 5:
            # random byte
            result = random_byte(result, pos, rng)
        elif op == 6:
            # delete bytes (only if input > 4 bytes)
            if len(result) > 4:
                length = rng.randint(1, min(4, len(result) - 1))
                result = delete_bytes(result, pos, length)
        elif op == 7:
            # insert random bytes
            length = rng.randint(1, 5)
            new_data = bytes(rng.randint(0, 256, size=length).astype(np.uint8))
            insert_pos = rng.randint(0, max(1, len(result)))
            result = insert_bytes(result, insert_pos, new_data)

    return result


def splice(data1: bytes, data2: bytes, rng: np.random.RandomState) -> bytes:
    """Splice two test cases at a random midpoint (AFL's splice stage)."""
    if len(data1) < 2 or len(data2) < 2:
        return data1

    min_len = min(len(data1), len(data2))
    split_pos = rng.randint(1, min_len)

    return data1[:split_pos] + data2[split_pos:min(len(data2), len(data1))]

    exec_time += 0.001 * len(edges_hit)
    return edges_hit, is_crash, exec_time

def get_total_edges(self) -> int:
    return self.total_edges

def get_crash_edges(self) -> Set[int]:
    return self.program.get_crash_edges()

def get_rare_edges(self) -> Set[int]:
    return self.program.get_rare_edges()

def get_target_blocks(self):
    return self.program.target_blocks

def get_distances(self, target_blocks=None) -> Dict[int, float]:
    if target_blocks is None:
        target_blocks = self.program.target_blocks
    return self.program.get_shortest_distances(target_blocks)

    for testcase in self.queue:
        testcase.is_favored = False
        testcase.unique_edges = set()
        for edge in testcase.coverage:
            coverage_map[edge].append(testcase)

    self.top_rated.clear()
    for edge, cases in coverage_map.items():
        self.top_rated[edge] = min(
            cases,
            key=lambda tc: (tc.size, tc.exec_time, -len(tc.coverage), tc.creation_time),
        )

    uncovered = set(self.global_edges)
    while uncovered:
        candidates = {self.top_rated[edge] for edge in uncovered if edge in self.top_rated}
        if not candidates:
            break
        best = max(
            candidates,
            key=lambda tc: (
                len(tc.coverage & uncovered),
                -tc.size,
                -tc.exec_time,
                tc.creation_time,
            ),
        )
        best.is_favored = True
        uncovered -= best.coverage

    edge_counts: Counter[int] = Counter()
    for testcase in self.queue:
        for edge in testcase.coverage:
            edge_counts[edge] += 1
    for testcase in self.queue:
        testcase.unique_edges = {edge for edge in testcase.coverage if edge_counts[edge] == 1}
        self.compute_perf_score(testcase)

def _register_interesting_testcase(
    self,
    data: bytes,
    outcome: ExecutionOutcome,
    depth: int,
    parent: Optional[TestCase],
    force: bool,
    trim: bool,
) -> Optional[TestCase]:
    new_edges = outcome.coverage - self.global_edges
    new_path = outcome.path_id not in self.unique_paths
    new_crash = outcome.is_crash and outcome.coverage_hash not in self.crashes

    if not force and not (new_edges or new_path or new_crash):
        return None

    calibration = self.calibrate(data)
    testcase = self.make_testcase(
        data=data,
        outcome=calibration.outcome,
        stability=calibration.stability,
        depth=depth,
        parent=parent,
    )
    if trim:
        testcase = self.trim_testcase(testcase)

    self.global_edges.update(testcase.coverage)
    self.unique_paths.add(testcase.path_id)
    self.bitmap.record_indexes(sorted(testcase.bitmap_indexes))
    self.extract_auto_dictionary(testcase.data)

    if testcase.is_crash:
        self.crashes.setdefault(testcase.coverage_hash, testcase)

    self.queue.append(testcase)
    self.cull_corpus()
    self.on_new_testcase(testcase, parent)
    return testcase

def add_seed(
    self,
    data: bytes,
    depth: int = 0,
    parent: Optional[TestCase] = None,
    force: bool = False,
    trim: bool = True,
) -> Optional[TestCase]:
    outcome = self.execute_input(data, parent=parent)
    return self._register_interesting_testcase(
        data=data,
        outcome=outcome,
        depth=depth,
        parent=parent,
        force=force,
        trim=trim,
    )

def choose_seed(self) -> Optional[TestCase]:
    if not self.queue:
        return None

    candidates = [testcase for testcase in self.queue if not testcase.is_crash] or list(self.queue)
    favored = [testcase for testcase in candidates if testcase.is_favored]
    if favored and self.rng.rand() < 0.75:
        pool = favored
    else:
        pool = candidates

    pool = sorted(pool, key=self.seed_priority_key)
    return pool[int(self.rng.randint(0, len(pool)))]

def seed_priority_key(self, testcase: TestCase) -> Tuple[float, ...]:
    return (
        testcase.was_fuzzed,
        testcase.times_chosen,
        -len(testcase.unique_edges),
        testcase.creation_time,
        testcase.size,
    )

def should_skip_seed(self, testcase: TestCase) -> bool:
    return False

def compute_energy(self, testcase: TestCase) -> int:
    self.compute_perf_score(testcase)
    return testcase.energy

def iter_bitflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    self.extract_auto_dictionary(data)
    max_bits = len(data) * 8
    for width in (1, 2, 4):
        for pos in range(0, max(0, max_bits - width + 1)):
            yield f"bitflip_{width}", bit_flip(data, pos, width)

def iter_byteflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    for width in (1, 2, 4):
        if len(data) < width:
            continue
        for pos in range(0, len(data) - width + 1):
            yield f"byteflip_{width * 8}", byte_flip(data, pos, width)

def iter_arith_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    for width in (1, 2, 4):
        if len(data) < width:
            continue
        endians = ("little", "big") if width > 1 else ("little",)
        for pos in range(0, len(data) - width + 1):
            for endian in endians:
                base_value = _read_int(data, pos, width, endian)
                for delta in range(1, 36):
                    yield f"arith_add_{width * 8}_{endian}", _write_int(
                        data,
                        pos,
                        width,
                        endian,
                        base_value + delta,
                    )
                    yield f"arith_sub_{width * 8}_{endian}", _write_int(
                        data,
                        pos,
                        width,
                        endian,
                        base_value - delta,
                    )

def iter_interesting_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    values_by_width = {
        1: INTERESTING_8,
        2: INTERESTING_16,
        4: INTERESTING_32,
    }
    for width, values in values_by_width.items():
        if len(data) < width:
            continue
        endians = ("little", "big") if width > 1 else ("little",)
        for pos in range(0, len(data) - width + 1):
            for endian in endians:
                for value in values:
                    yield f"interesting_{width * 8}_{endian}", _write_int(
                        data,
                        pos,
                        width,
                        endian,
                        value,
                    )

def iter_dictionary_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    dictionary = list(dict.fromkeys(self.user_dictionary + self.auto_dictionary))
    for token in dictionary:
        if not token:
            continue
        for pos in range(0, len(data) + 1):
            yield "dict_insert", insert_bytes(data, pos, token)
        if len(token) <= len(data):
            for pos in range(0, len(data) - len(token) + 1):
                yield "dict_overwrite", data[:pos] + token + data[pos + len(token):]

def iter_deterministic_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
    yielded: Set[str] = set()
    for iterator in (
        self.iter_bitflip_mutations(data),
        self.iter_byteflip_mutations(data),
        self.iter_arith_mutations(data),
        self.iter_interesting_mutations(data),
        self.iter_dictionary_mutations(data),
    ):
        for stage, mutated in iterator:
            if mutated == data:
                continue
            digest = _hash_bytes(mutated)
            if digest in yielded:
                continue
            yielded.add(digest)
            yield stage, mutated

def _apply_random_mutation(self, data: bytes) -> bytes:
    if not data:
        data = b"\x00"
    op = int(self.rng.randint(0, 10))
    pos = int(self.rng.randint(0, max(1, len(data))))

    if op == 0:
        bit_pos = int(self.rng.randint(0, max(1, len(data) * 8)))
        width = int(2 ** self.rng.randint(0, 3))
        return bit_flip(data, bit_pos, width)
    if op == 1:
        width = min(len(data), int(2 ** self.rng.randint(0, 3)))
        return byte_flip(data, min(pos, max(0, len(data) - width)), width)
    if op == 2:
        return arith_add(data, pos, int(self.rng.randint(1, 36)))
    if op == 3:
        return arith_sub(data, pos, int(self.rng.randint(1, 36)))
    if op == 4:
        width = min(len(data), int(2 ** self.rng.randint(0, 3)))
        if width not in (1, 2, 4):
            width = 1
        endian = "little" if width == 1 or self.rng.rand() < 0.5 else "big"
        values = {1: INTERESTING_8, 2: INTERESTING_16, 4: INTERESTING_32}[width]
        value = values[int(self.rng.randint(0, len(values)))]
        return _write_int(data, min(pos, max(0, len(data) - width)), width, endian, value)
    if op == 5:
        return random_byte(data, pos, self.rng)
    if op == 6 and len(data) > 1:
        length = int(self.rng.randint(1, min(len(data), 4) + 1))
        return delete_bytes(data, pos, length)
    if op == 7:
        length = int(self.rng.randint(1, 5))
        new_data = bytes(self.rng.randint(0, 256, size=length).astype(np.uint8))
        return insert_bytes(data, pos, new_data)
    if op == 8 and len(data) > 1:
        src = int(self.rng.randint(0, len(data)))
        max_len = min(4, len(data) - src)
        if max_len > 0:
            length = int(self.rng.randint(1, max_len + 1))
            dst = int(self.rng.randint(0, max(1, len(data) - length + 1)))
            return clone_bytes(data, src, dst, length)
    dictionary = self.user_dictionary + self.auto_dictionary
    if dictionary:
        token = dictionary[int(self.rng.randint(0, len(dictionary)))]
        return insert_bytes(data, pos, token)
    return data

def havoc_mutate(self, data: bytes, num_operations: Optional[int] = None) -> bytes:
    if num_operations is None:
        exponent = int(self.rng.randint(1, 8))
        num_operations = 2 ** exponent

    result = data
    for _ in range(max(1, num_operations)):
        result = self._apply_random_mutation(result)
    return result

def splice_with_havoc(self, left: bytes, right: bytes) -> bytes:
    if len(left) < 2 or len(right) < 2:
        return self.havoc_mutate(left)

    min_len = min(len(left), len(right))
    first_diff = next((idx for idx in range(min_len) if left[idx] != right[idx]), 0)
    last_diff = next(
        (idx for idx in range(min_len - 1, -1, -1) if left[idx] != right[idx]),
        min_len - 1,
    )
    split = (first_diff + last_diff) // 2
    spliced = left[:split] + right[split:]
    return self.havoc_mutate(spliced)

def process_mutation(self, parent: TestCase, mutated: bytes, stage: str) -> Optional[TestCase]:
    self.iteration += 1
    outcome = self.execute_input(mutated, parent=parent)
    testcase = self._register_interesting_testcase(
        data=mutated,
        outcome=outcome,
        depth=parent.depth + 1,
        parent=parent,
        force=False,
        trim=stage.startswith("dict") or stage.startswith("havoc"),
    )
    if testcase is not None:
        testcase.metadata["stage"] = stage
    return testcase

def run_deterministic_stages(self, testcase: TestCase, max_mutations: Optional[int] = None) -> int:
    count = 0
    for stage, mutated in self.iter_deterministic_mutations(testcase.data):
        self.process_mutation(testcase, mutated, stage)
        count += 1
        if max_mutations is not None and count >= max_mutations:
            break
    testcase.metadata["deterministic_done"] = 1.0
    return count

def run_havoc_stage(self, testcase: TestCase, cycles: Optional[int] = None) -> int:
    energy = cycles if cycles is not None else self.compute_energy(testcase)
    for _ in range(max(1, energy)):
        mutated = self.havoc_mutate(testcase.data)
        self.process_mutation(testcase, mutated, "havoc")
    return energy

def pick_splice_partner(self, testcase: TestCase) -> Optional[TestCase]:
    candidates = [other for other in self.queue if other is not testcase and not other.is_crash]
    if not candidates:
        return None
    candidates = sorted(candidates, key=lambda tc: (tc.times_chosen, tc.creation_time, tc.size))
    return candidates[int(self.rng.randint(0, len(candidates)))]

def run_splice_stage(self, testcase: TestCase, cycles: int = 4) -> int:
    partner = self.pick_splice_partner(testcase)
    if partner is None:
        return 0
    for _ in range(max(1, cycles)):
        mutated = self.splice_with_havoc(testcase.data, partner.data)
        self.process_mutation(testcase, mutated, "splice")
    return cycles

def fuzz_one(self, testcase: TestCase):
    if self.should_skip_seed(testcase):
        return
    testcase.times_chosen += 1
    testcase.fuzz_count += 1
    if not testcase.was_fuzzed:
        self.run_deterministic_stages(testcase)

        self.run_deterministic_stages(testcase)
    self.run_havoc_stage(testcase, cycles=max(1, self.compute_energy(testcase) // 8))
    self.run_splice_stage(testcase, cycles=2)
    testcase.was_fuzzed = True
    self.cull_corpus()

def bootstrap(self):
    for seed_input in self.initial_corpus:
        self.add_seed(seed_input, force=True)
    self.cull_corpus()

def run(self, iterations: int = 16) -> Dict[str, float]:
    if not self.queue and self.initial_corpus:
        self.bootstrap()

    for _ in range(iterations):
        testcase = self.choose_seed()
        if testcase is None:
            break
        self.fuzz_one(testcase)
    return self.get_stats()

def get_stats(self) -> Dict[str, float]:
    coverage = 0.0
    if self.total_edges:
        coverage = round(len(self.global_edges) / self.total_edges * 100.0, 1)
    return {
        "paths_discovered": float(len(self.unique_paths)),
        "unique_crashes": float(len(self.crashes)),
        "corpus_size": float(len(self.queue)),
        "edge_coverage": coverage,
        "executions": float(self.total_execs),
        "favored_seeds": float(sum(1 for testcase in self.queue if testcase.is_favored)),
        "forkserver_execs": float(self.forkserver.execs),
    }
